import { Pool } from 'pg';
import dotenv from 'dotenv';

dotenv.config();

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const sources = ['web-app', 'mobile-app', 'api-gateway'];
const metrics = ['cpu_usage', 'memory_usage', 'response_time', 'error_rate', 'request_count'];

function getBaseValue(metric: string): number {
  const bases: Record<string, number> = {
    cpu_usage: 55, memory_usage: 70, response_time: 150,
    error_rate: 2, request_count: 1000,
  };
  return bases[metric] || 50;
}

async function seedMetrics() {
  const now = Date.now();
  const thirtyDaysAgo = now - 30 * 24 * 60 * 60 * 1000;
  let count = 0;

  for (const source of sources) {
    for (const metric of metrics) {
      const baseValue = getBaseValue(metric);
      const values: string[] = [];
      for (let ts = thirtyDaysAgo; ts < now; ts += 5 * 60 * 1000) {
        const hourOfDay = new Date(ts).getHours();
        const dailyPattern = Math.sin((hourOfDay - 6) * Math.PI / 12) * 0.2;
        const noise = (Math.random() - 0.5) * 0.1;
        const spike = Math.random() > 0.995 ? Math.random() * 0.5 : 0;
        const value = baseValue * (1 + dailyPattern + noise + spike);
        values.push(`('${source}', '${metric}', ${value.toFixed(4)}, '${new Date(ts).toISOString()}')`);
        count++;
      }
      // Batch insert for performance
      const batchSize = 1000;
      for (let i = 0; i < values.length; i += batchSize) {
        const batch = values.slice(i, i + batchSize);
        await pool.query(
          `INSERT INTO metrics (source, metric_name, value, timestamp) VALUES ${batch.join(',')}
           ON CONFLICT DO NOTHING`
        );
      }
    }
  }
  console.log(`Seeded ${count} metrics`);
  await pool.end();
}

seedMetrics().catch(console.error);

