     EXTRACT(HOUR FROM timestamp)::int as hour_of_day,
     AVG(value) as avg_value, MAX(value) as max_value
     FROM metrics WHERE source = $1 AND metric_name = $2
     AND timestamp > NOW() - ($3 || ' days')::interval
     GROUP BY day_of_week, hour_of_day
     ORDER BY day_of_week, hour_of_day`,
    [source, metric, days]
