import { Fragment } from 'react';

interface HeatmapCell {
  day_of_week: number;
  hour_of_day: number;
  avg_value: number;
  max_value: number;
}

interface HeatmapProps {
  data: HeatmapCell[];
  title: string;
}

const days = ['Paz', 'Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt'];

export function Heatmap({ data, title }: HeatmapProps) {
  const maxVal = Math.max(...data.map(d => d.avg_value), 1);

  const getColor = (value: number) => {
    const intensity = value / maxVal;
    if (intensity > 0.8) return 'bg-red-500';
    if (intensity > 0.6) return 'bg-orange-400';
    if (intensity > 0.4) return 'bg-yellow-300';
    if (intensity > 0.2) return 'bg-green-300';
    return 'bg-green-100';
  };

  const getCell = (day: number, hour: number) =>
    data.find(d => d.day_of_week === day && d.hour_of_day === hour);

  return (
    <div className="bg-gray-800 rounded-lg p-4">
      <h3 className="font-medium text-gray-300 mb-4">{title}</h3>
      <div className="grid gap-1" style={{ gridTemplateColumns: 'auto repeat(24, 1fr)' }}>
        <div />
        {Array.from({ length: 24 }, (_, h) => (
          <div key={h} className="text-xs text-gray-400 text-center">{h}</div>
        ))}
        {days.map((day, d) => (
          <Fragment key={d}>
            <div className="text-xs text-gray-500 flex items-center pr-2">{day}</div>
            {Array.from({ length: 24 }, (_, h) => {
              const cell = getCell(d, h);
              return (
                <div
                  key={`${d}-${h}`}
                  className={`w-4 h-4 rounded-sm ${cell ? getColor(cell.avg_value) : 'bg-gray-700'} cursor-pointer`}
                  title={`${day} ${h}:00 - ${cell ? cell.avg_value.toFixed(1) : 'N/A'}`}
                />
              );
            })}
          </Fragment>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

export function useHeatmap(source: string, metric: string) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

